\begin{tikzpicture}[every node/.style={font=\large},scale=0.68]
\draw[->] (0,0)--(0,11.4); \draw[->] (0,0)--(10.2,0); \foreach \y in {2,4,6,8,10} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\y$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$};
