\foreach \x/\lab in {1.25/R1,3.55/R2,5.85/R3,8.15/R4} {\node[below,font=\scriptsize] at (\x,0) {\lab};} \draw[fill=gray!35] (6.55,10.15) rectangle (6.9,10.5); \node[right,font=\scriptsize] at (6.95,10.32) {Suns}; \draw (7.95,10.15) rectangle (8.3,10.5); \node[right,font=\scriptsize] at (8.35,10.32) {Waves};
